CREATE TABLE IF NOT EXISTS catalog_fee_agreements(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES catalog_accounts(id),service_fixed INTEGER NOT NULL CHECK(service_fixed>=0),service_bps INTEGER NOT NULL CHECK(service_bps BETWEEN 0 AND 10000),product_fixed INTEGER NOT NULL CHECK(product_fixed>=0),product_bps INTEGER NOT NULL CHECK(product_bps BETWEEN 0 AND 10000),ad_fixed INTEGER NOT NULL CHECK(ad_fixed>=0),ad_bps INTEGER NOT NULL CHECK(ad_bps BETWEEN 0 AND 10000),status TEXT NOT NULL DEFAULT 'proposed' CHECK(status IN('proposed','accepted','rejected')),created_by TEXT NOT NULL REFERENCES catalog_accounts(id),created_at TEXT NOT NULL,accepted_at TEXT);
CREATE TABLE IF NOT EXISTS catalog_source_links(kind TEXT NOT NULL CHECK(kind IN('salon','store')),source_id TEXT NOT NULL,owner_id TEXT NOT NULL REFERENCES catalog_accounts(id),PRIMARY KEY(kind,source_id));
CREATE TABLE IF NOT EXISTS catalog_financial_events(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES catalog_accounts(id),kind TEXT NOT NULL CHECK(kind IN('service','product','ad')),source_id TEXT NOT NULL,base_amount INTEGER NOT NULL CHECK(base_amount>=0),admin_due INTEGER NOT NULL CHECK(admin_due>=0),agreement_id TEXT NOT NULL REFERENCES catalog_fee_agreements(id),occurred_at TEXT NOT NULL,UNIQUE(kind,source_id));
CREATE TABLE IF NOT EXISTS catalog_cash_receipts(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES catalog_accounts(id),event_id TEXT NOT NULL REFERENCES catalog_financial_events(id),amount INTEGER NOT NULL CHECK(amount>0),channel TEXT NOT NULL CHECK(channel IN('customer','courier')),reference TEXT NOT NULL,recorded_at TEXT NOT NULL,request_key TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS catalog_admin_payments(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES catalog_accounts(id),amount INTEGER NOT NULL CHECK(amount>0),reference TEXT NOT NULL,recorded_by TEXT NOT NULL REFERENCES catalog_accounts(id),recorded_at TEXT NOT NULL,request_key TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS catalog_delivery_grants(account_id TEXT PRIMARY KEY REFERENCES catalog_accounts(id),legacy_courier_id TEXT NOT NULL,granted_by TEXT NOT NULL REFERENCES catalog_accounts(id),created_at TEXT NOT NULL);

CREATE TABLE IF NOT EXISTS catalog_payment_notifications(payment_id TEXT PRIMARY KEY REFERENCES catalog_admin_payments(id),owner_id TEXT NOT NULL REFERENCES catalog_accounts(id),read_at TEXT);
CREATE INDEX IF NOT EXISTS catalog_payment_notifications_owner ON catalog_payment_notifications(owner_id,read_at);
CREATE TRIGGER IF NOT EXISTS catalog_notify_admin_payment AFTER INSERT ON catalog_admin_payments BEGIN INSERT INTO catalog_payment_notifications(payment_id,owner_id) VALUES(NEW.id,NEW.owner_id); END;

CREATE TABLE IF NOT EXISTS catalog_admin_expenses(id TEXT PRIMARY KEY,owner_id TEXT REFERENCES catalog_accounts(id),description TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),reference TEXT NOT NULL DEFAULT '',expense_date TEXT NOT NULL,recorded_by TEXT NOT NULL REFERENCES catalog_accounts(id),recorded_at TEXT NOT NULL,request_key TEXT NOT NULL UNIQUE);
CREATE INDEX IF NOT EXISTS catalog_admin_expenses_owner ON catalog_admin_expenses(owner_id,expense_date);
